import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"神经网络直觉","description":"","frontmatter":{},"headers":[],"relativePath":"ai/neural-networks.md","filePath":"ai/neural-networks.md","lastUpdated":1788308924000}'),s={name:"ai/neural-networks.md"};function n(r,a,o,d,p,h){return t(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="神经网络直觉" tabindex="-1">神经网络直觉 <a class="header-anchor" href="#神经网络直觉" aria-label="Permalink to &quot;神经网络直觉&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> 神经网络把许多可调的计算单元分层连接起来，通过损失函数提供方向，再用反向传播和梯度下降逐步调整权重与偏置。</p></blockquote><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>已阅读 <a href="/ai/machine-learning">机器学习入门</a>，理解特征、标签、训练、验证和泛化。</li><li>知道模型参数是在训练中调整的数字。</li><li>不要求微积分基础；本页只解释计算方向，不推导偏导数和链式法则。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>解释神经元、层、权重和偏置分别做什么。</li><li>说明为什么神经网络需要激活函数。</li><li>按顺序描述前向计算、损失计算、反向传播和参数更新。</li><li>区分损失函数、梯度与梯度下降。</li><li>说明神经网络与深度学习之间的关系。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="神经元、权重和偏置" tabindex="-1">神经元、权重和偏置 <a class="header-anchor" href="#神经元、权重和偏置" aria-label="Permalink to &quot;神经元、权重和偏置&quot;">​</a></h3><p>人工神经元不是生物神经元的完整模拟，而是一个可训练的计算单元。它先对输入做加权求和，再加上偏置：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>z = w1*x1 + w2*x2 + ... + wn*xn + b</span></span>
<span class="line"><span>输出 = 激活函数(z)</span></span></code></pre></div><ul><li><code>x</code> 是输入特征或上一层输出。</li><li><code>w</code> 是权重（Weight），决定每个输入影响有多大、方向是正还是负。</li><li><code>b</code> 是偏置（Bias），让神经元不必在所有输入为零时也固定输出零。</li></ul><p>训练神经网络的核心，就是找到一组能让预测误差更小的权重和偏置。</p><h3 id="层与网络" tabindex="-1">层与网络 <a class="header-anchor" href="#层与网络" aria-label="Permalink to &quot;层与网络&quot;">​</a></h3><p>神经元通常按层组织：</p><ul><li><strong>输入层</strong>：接收原始特征，本身通常不做复杂学习。</li><li><strong>隐藏层</strong>：逐层组合输入，形成更抽象的表示。</li><li><strong>输出层</strong>：产生分类概率、数值或其他任务输出。</li></ul><p>一个网络可以有多个隐藏层。深度学习（Deep Learning）通常指使用多层神经网络从数据中学习分层表示的方法。“深”描述的是网络结构层次，不代表模型拥有更深刻的主观理解。</p><h3 id="激活函数" tabindex="-1">激活函数 <a class="header-anchor" href="#激活函数" aria-label="Permalink to &quot;激活函数&quot;">​</a></h3><p>如果每层都只做线性加权，多层线性计算仍可合并成一次线性计算，网络很难表示弯曲的决策边界。激活函数（Activation Function）引入非线性。</p><p>常见函数包括：</p><ul><li><strong>ReLU</strong>：负数输出 0，正数保持不变；常用于隐藏层。</li><li><strong>Sigmoid</strong>：把数值压到 0 与 1 之间；常用于二分类输出，但深层隐藏层中可能出现梯度过小。</li><li><strong>Tanh</strong>：把数值压到 -1 与 1 之间。</li><li><strong>Softmax</strong>：把一组原始分数（Logit，下一章的推理与解码页会细讲）转成总和为 1 的概率，常用于输出层。</li></ul><p>激活函数的选择会影响表达能力、梯度传播和训练稳定性。</p><h3 id="前向计算" tabindex="-1">前向计算 <a class="header-anchor" href="#前向计算" aria-label="Permalink to &quot;前向计算&quot;">​</a></h3><p>前向计算（Forward Pass）是从输入到输出依次计算：</p><ol><li>输入进入第一层。</li><li>每个神经元计算加权和与激活值。</li><li>当前层输出成为下一层输入。</li><li>输出层给出最终预测。</li></ol><p>推理阶段主要执行前向计算。训练阶段在前向计算后，还要比较预测与目标并更新参数。</p><h3 id="损失函数" tabindex="-1">损失函数 <a class="header-anchor" href="#损失函数" aria-label="Permalink to &quot;损失函数&quot;">​</a></h3><p>损失函数（Loss Function）把“预测有多不对”变成一个可优化的数值。</p><ul><li>回归任务常用均方误差或平均绝对误差。</li><li>分类任务常用交叉熵。</li><li>生成模型会根据训练目标使用 Token 级交叉熵或其他损失。</li></ul><p>损失越小通常表示模型更符合当前训练目标，但不代表真实业务一定更好。数据偏差、错误标签和不合适的目标函数都可能让“低损失”与“有用”分离。</p><h3 id="反向传播与梯度下降" tabindex="-1">反向传播与梯度下降 <a class="header-anchor" href="#反向传播与梯度下降" aria-label="Permalink to &quot;反向传播与梯度下降&quot;">​</a></h3><p>**梯度（Gradient）**可以直观理解为：某个参数稍微变化时，损失会朝哪个方向、以多快速度变化。</p><p>**反向传播（Backpropagation）**从输出层向前计算每个参数对损失的影响。它高效复用了链式法则中的中间结果，本身负责“算梯度”。</p><p>**梯度下降（Gradient Descent）**使用这些梯度更新参数：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新参数 = 旧参数 - 学习率 * 梯度</span></span></code></pre></div><p>学习率决定每次走多大一步。太大可能越过较好位置甚至发散，太小则训练缓慢。实际训练通常使用小批量数据和 Adam 等优化器，但核心直觉仍是沿着降低损失的方向更新参数。</p><h2 id="最小推演-训练一个神经元" tabindex="-1">最小推演：训练一个神经元 <a class="header-anchor" href="#最小推演-训练一个神经元" aria-label="Permalink to &quot;最小推演：训练一个神经元&quot;">​</a></h2><p>假设一个神经元有两个输入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x1 = 1.0, x2 = 0.5</span></span>
<span class="line"><span>w1 = 0.8, w2 = -0.4, b = -0.1</span></span></code></pre></div><p>使用 ReLU 激活：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>z = 0.8*1.0 + (-0.4)*0.5 - 0.1 = 0.5</span></span>
<span class="line"><span>预测值 = ReLU(0.5) = 0.5</span></span></code></pre></div><p>若目标值是 <code>1.0</code>，使用平方误差：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>损失 = (预测值 - 目标值)^2 = (0.5 - 1.0)^2 = 0.25</span></span></code></pre></div><p>在这个位置，增大 <code>w1</code> 会让预测更接近目标。若学习率为 <code>0.1</code>，梯度计算得到 <code>w1</code> 的梯度为 <code>-1.0</code>（对平方误差，<code>w1</code> 的梯度 = 2×(预测−目标)×输入 = 2×(0.5−1.0)×1.0 = −1.0），则：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新 w1 = 0.8 - 0.1*(-1.0) = 0.9</span></span>
<span class="line"><span>新预测 = ReLU(0.9 - 0.2 - 0.1) = 0.6</span></span>
<span class="line"><span>新损失 = (0.6 - 1.0)^2 = 0.16</span></span></code></pre></div><p>一次更新后损失从 <code>0.25</code> 降到 <code>0.16</code>。真实神经网络会同时更新大量参数，并在许多批次上重复这个过程；单次下降不保证最终一定泛化良好。</p><h2 id="对比表" tabindex="-1">对比表 <a class="header-anchor" href="#对比表" aria-label="Permalink to &quot;对比表&quot;">​</a></h2><p>把本页的核心概念放在一起对比：</p><table tabindex="0"><thead><tr><th>概念</th><th>回答的问题</th><th>是否在训练中变化</th><th>常见误解</th></tr></thead><tbody><tr><td>权重（Weight）</td><td>某个输入影响多大、方向如何</td><td>是</td><td>权重越大就一定越重要</td></tr><tr><td>偏置（Bias）</td><td>整体激活门槛如何平移</td><td>是</td><td>与数据偏见或公平性中的 bias 完全相同</td></tr><tr><td>激活函数</td><td>如何引入非线性或形成输出范围</td><td>通常否</td><td>任意激活函数都能互换</td></tr><tr><td>损失函数</td><td>当前预测离训练目标多远</td><td>公式通常固定，数值变化</td><td>损失低就一定满足业务目标</td></tr><tr><td>梯度</td><td>参数微调会怎样影响损失</td><td>每步重新计算</td><td>梯度就是参数更新后的值</td></tr><tr><td>优化器</td><td>如何根据梯度更新参数</td><td>状态会变化</td><td>优化器能自动解决数据和目标错误</td></tr></tbody></table><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“神经元像人脑一样思考”</strong>：人工神经元是受启发的数学单元，不等同于生物神经系统。</li><li><strong>“层数越多越好”</strong>：更深的网络需要合适的数据、结构、优化和正则化。</li><li><strong>“反向传播就是梯度下降”</strong>：反向传播计算梯度，梯度下降或其他优化器使用梯度更新参数。</li><li><strong>“激活函数只改变输出范围”</strong>：它还决定网络能否表达非线性关系，并影响梯度传播。</li><li><strong>“训练损失下降就完成了”</strong>：还要检查验证指标、过拟合、鲁棒性和真实场景表现。</li><li><strong>“Bias 一定指社会偏见”</strong>：本页 Bias 是神经元参数；数据偏差与公平性是另一层问题。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-为什么多层网络不能全部省略激活函数" tabindex="-1">1. 为什么多层网络不能全部省略激活函数？ <a class="header-anchor" href="#_1-为什么多层网络不能全部省略激活函数" aria-label="Permalink to &quot;1. 为什么多层网络不能全部省略激活函数？&quot;">​</a></h3><details><summary>查看答案</summary><p>因为多层纯线性变换仍可合并成一次线性变换，无法表达复杂的非线性关系。激活函数让网络形成弯曲、分段或更复杂的映射。</p></details><h3 id="_2-反向传播和梯度下降分别负责什么" tabindex="-1">2. 反向传播和梯度下降分别负责什么？ <a class="header-anchor" href="#_2-反向传播和梯度下降分别负责什么" aria-label="Permalink to &quot;2. 反向传播和梯度下降分别负责什么？&quot;">​</a></h3><details><summary>查看答案</summary><p>反向传播高效计算各参数对损失的梯度；梯度下降或其他优化器根据梯度和学习率更新参数。</p></details><h3 id="_3-训练损失持续下降而验证损失开始上升-最可能说明什么" tabindex="-1">3. 训练损失持续下降而验证损失开始上升，最可能说明什么？ <a class="header-anchor" href="#_3-训练损失持续下降而验证损失开始上升-最可能说明什么" aria-label="Permalink to &quot;3. 训练损失持续下降而验证损失开始上升，最可能说明什么？&quot;">​</a></h3><details><summary>查看答案</summary><p>最可能出现了过拟合：模型继续适应训练数据的细节，却降低了对未见数据的泛化能力。</p></details><h2 id="下一步阅读" tabindex="-1">下一步阅读 <a class="header-anchor" href="#下一步阅读" aria-label="Permalink to &quot;下一步阅读&quot;">​</a></h2><ul><li>上一篇：<a href="/ai/machine-learning">机器学习入门</a>：先建立数据、训练与泛化的框架，再看网络内部怎么算。</li><li>下一篇：<a href="/llm/basics">大模型入门</a>：把神经网络的直觉接到 LLM 的整体图景上。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><ul><li><a href="https://developers.google.com/machine-learning/crash-course/neural-networks" target="_blank" rel="noreferrer">Google Machine Learning Crash Course：Neural Networks</a>：神经网络单元的官方课程页。</li><li><a href="https://developers.google.com/machine-learning/crash-course/neural-networks/backpropagation" target="_blank" rel="noreferrer">Google：Training using backpropagation</a>：反向传播训练过程的官方讲解。</li><li><a href="https://www.deeplearningbook.org/contents/mlp.html" target="_blank" rel="noreferrer">Goodfellow、Bengio 与 Courville：《Deep Learning》第 6 章</a>：多层感知机的经典教材章节。</li><li><a href="https://doi.org/10.1038/323533a0" target="_blank" rel="noreferrer">Rumelhart、Hinton 与 Williams：Learning representations by back-propagating errors</a>：首次提出反向传播的原始论文。</li></ul>`,62)])])}const g=e(s,[["render",n]]);export{u as __pageData,g as default};
